package com.sharesphere.booking.api;

import com.sharesphere.booking.domain.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.amqp.rabbit.core.RabbitTemplate;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.client.RestClient;

@RestController @RequestMapping("/api/bookings")
public class BookingController {
    private final BookingRepository bookings;private final NegotiationOfferRepository offers;private final DisputeCaseRepository disputes;private final RabbitTemplate events;private final String internalToken;private final RestClient borrowCircle;private final RestClient communities;
    public BookingController(BookingRepository bookings,NegotiationOfferRepository offers,DisputeCaseRepository disputes,RabbitTemplate events,@Value("${sharesphere.internal.token}")String internalToken,@Value("${services.borrowcircle:http://localhost:8083}")String borrowUrl,@Value("${services.community:http://localhost:8082}")String communityUrl){this.bookings=bookings;this.offers=offers;this.disputes=disputes;this.events=events;this.internalToken=internalToken;this.borrowCircle=RestClient.builder().baseUrl(borrowUrl).build();this.communities=RestClient.builder().baseUrl(communityUrl).build();}

    @GetMapping public List<BookingView> mine(@RequestHeader("X-User-Email") String email){return bookings.findByRequesterEmailIgnoreCaseOrProviderEmailIgnoreCaseOrderByCreatedAtDesc(email,email).stream().map(this::view).toList();}
    @GetMapping("/{id}") public BookingView get(@PathVariable UUID id,@RequestHeader("X-User-Email") String email){Booking b=find(id);authorize(b,email);return view(b);}
    @PostMapping @ResponseStatus(HttpStatus.CREATED) public BookingView create(@Valid @RequestBody CreateBooking req,@RequestHeader("X-User-Email") String email){
        Map<?,?> listing=listing(req.listingId());
        String actualProvider=String.valueOf(listing.get("providerEmail"));if(actualProvider.equalsIgnoreCase(email))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"You cannot request your own listing");if(!actualProvider.equalsIgnoreCase(req.providerEmail()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Provider does not match the listing owner");
        String visibility=String.valueOf(listing.get("visibility"));String communityId=String.valueOf(listing.get("communityId"));if("COMMUNITY".equalsIgnoreCase(visibility)){try{Boolean member=communities.get().uri("/api/communities/internal/{id}/members/{email}",communityId,email).header("X-Internal-Token",internalToken).retrieve().body(Boolean.class);if(!Boolean.TRUE.equals(member))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This listing is limited to its community members");}catch(ResponseStatusException ex){throw ex;}catch(Exception ex){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Community access could not be verified",ex);}}
        if(req.endDate().isBefore(req.startDate()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"End date must be on or after the start date");
        if(req.startDate().isBefore(LocalDate.now()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Start date cannot be in the past");
        if(listing.get("availableFrom")!=null&&req.startDate().isBefore(LocalDate.parse(String.valueOf(listing.get("availableFrom")))))throw new ResponseStatusException(HttpStatus.CONFLICT,"The listing is not available by the requested start date");
        if(listing.get("availableTo")!=null&&req.endDate().isAfter(LocalDate.parse(String.valueOf(listing.get("availableTo")))))throw new ResponseStatusException(HttpStatus.CONFLICT,"The requested end date is outside the listing's availability");
        Set<String> blocking=Set.of("REQUESTED","NEGOTIATING","PENDING_PAYMENT","READY_FOR_HANDOVER","ACTIVE","RETURN_PENDING");
        boolean overlaps=bookings.findByListingIdAndStatusIn(req.listingId(),blocking).stream().anyMatch(existing->!req.startDate().isAfter(existing.getEndDate())&&!req.endDate().isBefore(existing.getStartDate()));
        if(overlaps)throw new ResponseStatusException(HttpStatus.CONFLICT,"This item already has a request covering those dates");
        validateTerms(req.exchangeType(),req.proposedPriceInr());enforceListingTerms(listing,req.exchangeType(),req.proposedPriceInr());
        Booking b=bookings.save(new Booking(req.listingId(),email,req.providerEmail(),req.exchangeType(),req.proposedPriceInr(),req.startDate(),req.endDate(),req.reason()));
        offers.save(new NegotiationOffer(b.getId(),email,b.getExchangeType(),b.getAgreedPriceInr(),req.reason()));publish(b,"booking.requested",email,req.reason());return view(b);
    }
    @PostMapping("/{id}/offers") @ResponseStatus(HttpStatus.CREATED) public BookingView offer(@PathVariable UUID id,@Valid @RequestBody OfferRequest req,@RequestHeader("X-User-Email") String email){
        Booking b=find(id);authorize(b,email);if(Set.of("APPROVED","PENDING_PAYMENT","READY_FOR_HANDOVER","ACTIVE","COMPLETED","DECLINED","CANCELLED").contains(b.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Negotiation is closed for this booking");Map<?,?> listing=listing(b.getListingId());if(!Boolean.TRUE.equals(listing.get("negotiable")))throw new ResponseStatusException(HttpStatus.CONFLICT,"This listing is not open to negotiation");validateTerms(req.exchangeType(),req.amountInr());
        offers.save(new NegotiationOffer(id,email,req.exchangeType().toUpperCase(),req.amountInr(),req.reason()));b.negotiate(req.exchangeType(),req.amountInr(),req.reason(),email);b=bookings.save(b);publish(b,"booking.offer",email,req.reason());return view(b);
    }
    @PostMapping("/{id}/offers/{offerId}/accept") public BookingView acceptOffer(@PathVariable UUID id,@PathVariable UUID offerId,@RequestHeader("X-User-Email")String email){Booking b=find(id);authorize(b,email);if(!b.getStatus().equals("NEGOTIATING"))throw new ResponseStatusException(HttpStatus.CONFLICT,"There is no open counteroffer");NegotiationOffer offer=offers.findById(offerId).filter(o->o.getBookingId().equals(id)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Offer not found"));if(offer.getSenderEmail().equalsIgnoreCase(email))throw new ResponseStatusException(HttpStatus.CONFLICT,"You cannot accept your own offer");if(offer.getAcceptedAt()!=null)throw new ResponseStatusException(HttpStatus.CONFLICT,"This offer is already accepted");offer.markAccepted();offers.save(offer);b.acceptOffer(offer.getExchangeType(),offer.getAmountInr(),offer.getReason(),email);b=bookings.save(b);publish(b,"booking.terms_accepted",email,"Counteroffer accepted");return view(b);}
    @PostMapping("/{id}/approve") public BookingView approve(@PathVariable UUID id,@RequestHeader("X-User-Email") String email){Booking b=find(id);if(!b.getProviderEmail().equalsIgnoreCase(email))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the provider can approve this request");if(!Set.of("REQUESTED","NEGOTIATING").contains(b.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Booking is not awaiting provider approval");if(b.getLastOfferBy().equalsIgnoreCase(b.getProviderEmail()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Requester must accept the provider's counteroffer before approval");b.approve();b=bookings.save(b);publish(b,"booking.approved",email,"Provider approved the agreed terms");return view(b);}
    @PostMapping("/{id}/decline") public BookingView decline(@PathVariable UUID id,@RequestHeader("X-User-Email") String email){Booking b=find(id);if(!b.getProviderEmail().equalsIgnoreCase(email))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the provider can decline this request");if(!Set.of("REQUESTED","NEGOTIATING").contains(b.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Booking is not awaiting provider approval");b.decline();b=bookings.save(b);publish(b,"booking.declined",email,"Provider declined the request");return view(b);}
    @PostMapping("/{id}/cancel") public BookingView cancel(@PathVariable UUID id,@RequestHeader("X-User-Email") String email){Booking b=find(id);authorize(b,email);if(!Set.of("REQUESTED","NEGOTIATING").contains(b.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"This booking can no longer be cancelled from the request flow");b.cancel();b=bookings.save(b);publish(b,"booking.cancelled",email,"Request cancelled");return view(b);}
    @PostMapping("/internal/{id}/payment-confirmed") public BookingView paymentConfirmed(@PathVariable UUID id,@RequestHeader("X-Internal-Token")String token){checkInternal(token);Booking b=find(id);if(b.getStatus().equals("READY_FOR_HANDOVER"))return view(b);try{b.paymentConfirmed();}catch(IllegalStateException ex){throw new ResponseStatusException(HttpStatus.CONFLICT,ex.getMessage());}return view(bookings.save(b));}
    @PostMapping("/{id}/handover") public BookingView handover(@PathVariable UUID id,@RequestHeader("X-User-Email") String email){Booking b=find(id);authorize(b,email);if(!b.getStatus().equals("READY_FOR_HANDOVER"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Approval and any required payment must be complete before handover");b.handover();b=bookings.save(b);publish(b,"booking.handover",email,"Handover recorded");return view(b);}
    @PostMapping("/{id}/return") public BookingView requestReturn(@PathVariable UUID id,@RequestHeader("X-User-Email") String email){Booking b=find(id);authorize(b,email);if(!b.getStatus().equals("ACTIVE"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only active exchanges can be returned");b.requestReturn();return view(bookings.save(b));}
    @PostMapping("/{id}/confirm-return") public BookingView confirmReturn(@PathVariable UUID id,@RequestHeader("X-User-Email") String email){Booking b=find(id);if(!b.getProviderEmail().equalsIgnoreCase(email))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the provider confirms a return");if(!b.getStatus().equals("RETURN_PENDING"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Return has not been requested");b.confirmReturn();b=bookings.save(b);publish(b,"booking.completed",email,"Return was confirmed");return view(b);}
    @PostMapping("/{id}/dispute") public BookingView dispute(@PathVariable UUID id,@Valid @RequestBody DisputeRequest request,@RequestHeader("X-User-Email") String email){Booking b=find(id);authorize(b,email);if(!Set.of("APPROVED","PENDING_PAYMENT","READY_FOR_HANDOVER","ACTIVE","RETURN_PENDING").contains(b.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"This booking cannot be disputed in its current state");b.dispute();b=bookings.save(b);disputes.save(new DisputeCase(id,email,request.reason()));publish(b,"booking.disputed",email,request.reason());return view(b);}
    @GetMapping("/{id}/offers") public List<OfferView> offerHistory(@PathVariable UUID id,@RequestHeader("X-User-Email") String email){Booking b=find(id);authorize(b,email);return offers.findByBookingIdOrderByCreatedAtAsc(id).stream().map(o->new OfferView(o.getId(),o.getSenderEmail(),o.getExchangeType(),o.getAmountInr(),o.getReason(),o.getCreatedAt(),o.getAcceptedAt())).toList();}
    @GetMapping("/internal/disputes") public List<DisputeView> adminDisputes(@RequestHeader("X-Internal-Token")String token){checkInternal(token);return disputes.findAllByOrderByCreatedAtDesc().stream().map(this::disputeView).toList();}
    @GetMapping("/internal/{id}/payment-details") public PaymentDetails paymentDetails(@PathVariable UUID id,@RequestHeader("X-Internal-Token")String token){checkInternal(token);Booking b=find(id);return new PaymentDetails(b.getId(),b.getRequesterEmail(),b.getProviderEmail(),b.getAgreedPriceInr(),"INR",b.getStatus());}
    @PostMapping("/internal/disputes/{id}/resolve") public DisputeView resolveDispute(@PathVariable UUID id,@RequestHeader("X-Internal-Token")String token,@RequestBody ResolveDispute request){checkInternal(token);DisputeCase d=disputes.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Dispute not found"));if(!d.getStatus().equals("OPEN"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Dispute is already resolved");d.resolve(request.adminEmail(),request.resolution());disputes.save(d);return disputeView(d);}

    private Booking find(UUID id){return bookings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));}
    private Map<?,?> listing(UUID id){try{return borrowCircle.get().uri("/api/borrowcircle/listings/{id}",id).retrieve().body(Map.class);}catch(Exception exception){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Listing is unavailable",exception);}}
    private void enforceListingTerms(Map<?,?> listing,String type,BigDecimal amount){
        if(Boolean.TRUE.equals(listing.get("negotiable")))return;
        String listedType=String.valueOf(listing.get("exchangeType"));
        BigDecimal listedPrice=listing.get("price") == null ? null : new BigDecimal(String.valueOf(listing.get("price")));
        if(!listedType.equalsIgnoreCase(type)||!Objects.equals(listedPrice==null?null:listedPrice.stripTrailingZeros(),amount==null?null:amount.stripTrailingZeros()))
            throw new ResponseStatusException(HttpStatus.CONFLICT,"This listing is not open to different exchange terms");
    }
    private void checkInternal(String token){if(!internalToken.equals(token))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Internal service authentication failed");}
    private DisputeView disputeView(DisputeCase d){return new DisputeView(d.getId(),d.getBookingId(),d.getOpenedBy(),d.getReason(),d.getStatus(),d.getResolvedBy(),d.getResolution(),d.getCreatedAt(),d.getResolvedAt());}
    private void publish(Booking b,String eventType,String actor,String reason){events.convertAndSend("sharesphere.events",eventType,Map.of("eventType",eventType,"bookingId",b.getId().toString(),"requesterEmail",b.getRequesterEmail(),"providerEmail",b.getProviderEmail(),"actorEmail",actor,"status",b.getStatus(),"reason",reason,"occurredAt",java.time.Instant.now().toString()));}
    private void authorize(Booking b,String email){if(!b.getRequesterEmail().equalsIgnoreCase(email)&&!b.getProviderEmail().equalsIgnoreCase(email))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Booking participants only");}
    private void validateTerms(String type,BigDecimal price){if(type==null||!Set.of("PAID","FREE").contains(type.toUpperCase()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Exchange type must be PAID or FREE");if(type.equalsIgnoreCase("PAID")&&(price==null||price.signum()<=0))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Paid exchanges need a positive INR amount");if(type.equalsIgnoreCase("FREE")&&price!=null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Free exchanges cannot have a price");if(price!=null&&price.signum()<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Amount cannot be negative");}
    private BookingView view(Booking b){return new BookingView(b.getId(),b.getListingId(),b.getRequesterEmail(),b.getProviderEmail(),b.getStatus(),b.getExchangeType(),b.getAgreedPriceInr(),"INR",b.getStartDate(),b.getEndDate(),b.getReason(),offers.findByBookingIdOrderByCreatedAtAsc(b.getId()).stream().map(o->new OfferView(o.getId(),o.getSenderEmail(),o.getExchangeType(),o.getAmountInr(),o.getReason(),o.getCreatedAt(),o.getAcceptedAt())).toList(),b.getCreatedAt(),b.getApprovedAt(),b.getHandoverAt(),b.getReturnedAt());}
    public record CreateBooking(@NotNull UUID listingId,@NotBlank @Email String providerEmail,@NotBlank String exchangeType,@DecimalMin("0.0") @Digits(integer=8,fraction=2) BigDecimal proposedPriceInr,@NotNull LocalDate startDate,@NotNull LocalDate endDate,@NotBlank @Size(max=600) String reason){}
    public record OfferRequest(@NotBlank String exchangeType,@DecimalMin("0.0") @Digits(integer=8,fraction=2) BigDecimal amountInr,@NotBlank @Size(max=600) String reason){}
    public record DisputeRequest(@NotBlank @Size(min=8,max=1200) String reason){}
    public record ResolveDispute(@NotBlank String adminEmail,@NotBlank @Size(max=1200) String resolution){}
    public record DisputeView(UUID id,UUID bookingId,String openedBy,String reason,String status,String resolvedBy,String resolution,java.time.Instant createdAt,java.time.Instant resolvedAt){}
    public record PaymentDetails(UUID bookingId,String requesterEmail,String providerEmail,BigDecimal amountInr,String currency,String status){}
    public record OfferView(UUID id,String senderEmail,String exchangeType,BigDecimal amountInr,String reason,java.time.Instant createdAt,java.time.Instant acceptedAt){}
    public record BookingView(UUID id,UUID listingId,String requesterEmail,String providerEmail,String status,String exchangeType,BigDecimal agreedPriceInr,String currency,LocalDate startDate,LocalDate endDate,String reason,List<OfferView> negotiation,java.time.Instant createdAt,java.time.Instant approvedAt,java.time.Instant handoverAt,java.time.Instant returnedAt){}
}
